# Loopback, serial clients. A client must half-close writes before reading replies.
def kv_receive(peer: tcpsocket, timeout: int) -> str:
    pending = bytearray()
    while True:
        if peer.wait_readable(timeout) == 0:
            raise OSError
        chunk = peer.recv(8192)
        if len(chunk) == 0:
            return bytes(pending).decode('utf-8')
        if len(chunk) > 8388608 - len(pending):
            raise ValueError
        pending.extend(chunk)
    return ''

def kv_send(peer: tcpsocket, data: bytes, timeout: int) -> None:
    position: int = 0
    while position < len(data):
        if peer.wait_writable(timeout) == 0:
            raise OSError
        sent = peer.send_some(data[position:])
        if sent <= 0:
            raise OSError
        position += sent

